/* =========================================================
   =========================================================
   HAPL - INVESTOR INFORMATION DASHBOARD
   =========================================================

   MAINTENANCE GUIDE
   ---------------------------------------------------------
   IMPORTANT URLS:

   Investor Dashboard:
   /investor-information-new/

   Financial Results:
   /financial-results/

   Annual Reports & Returns:
   /annual-reports-returns/

   Regulatory Filings:
   /regulatory-filings/

   Shareholding Patterns:
   /shareholding-patterns/

   AGM / EGM:
   /agm-egm/

   Board Meetings:
   /board-meetings/

   Corporate Announcements:
   /corporate-announcements/

   Investor Contact:
   /investor-contact-shareholder-information/

   Registrar & Bank Details:
   /registrar-bank-details/

   Board Directors:
   /board-directors/

   Key Managerial Personnel:
   /key-managerial-personnel/

   Investor Grievance:
   /investor-grievance/

   Latest Updates:
   /latest-updates/

   IMPORTANT:
   - Do not use "#" for document/page links.
   - Do not add fake PDF URLs.
   - If a document is unavailable, use the Coming Soon template.
   - Verify WordPress slug before publishing.
   ========================================================= */


/* =========================================================
   BASE
   ========================================================= */

.hapl-investor {
    font-family: Arial, sans-serif;
    color: #132b52;
    background: #f6f9fd;
}


/* =========================================================
   HERO
   ========================================================= */

.hapl-hero {
    position: relative;
    overflow: hidden;

    min-height: 250px;

    display: flex;
    align-items: center;

    box-sizing: border-box;

    background:
        linear-gradient(
            105deg,
            #062b63 0%,
            #0b438c 55%,
            #075ca8 100%
        );

    color: #fff;

    padding: 58px 55px;
}

.hapl-hero-inner {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
}

.hapl-accent {
    width: 38px;
    height: 4px;

    background: #4da3ff;

    margin-bottom: 18px;
}

.hapl-hero h1 {
    margin: 0 0 12px;

    color: #fff;

    font-size: 40px;
    line-height: 1.2;
    font-weight: 700;
}

.hapl-hero p {
    max-width: 700px;

    margin: 0;

    color: #eef6ff;

    font-size: 17px;
    line-height: 1.65;
}


/* =========================================================
   DASHBOARD
   ========================================================= */

.hapl-dashboard {
    max-width: 1200px;

    margin: 22px auto 30px;

    padding: 0 18px;

    box-sizing: border-box;
}

.hapl-dashboard-grid {
    display: grid;

    grid-template-columns:
        290px
        minmax(0, 1fr);

    gap: 18px;

    align-items: stretch;
}


/* =========================================================
   LEFT CATEGORY PANEL
   ========================================================= */

.hapl-category-panel {
    background: #fff;

    border: 1px solid #e3eaf3;

    border-radius: 10px;

    padding: 20px 15px;

    box-shadow:
        0 3px 14px rgba(25, 55, 95, 0.05);

    box-sizing: border-box;
}

.hapl-category-panel h2 {
    margin: 0 0 14px;

    color: #102b5c;

    font-size: 18px;
    font-weight: 700;
}


/* =========================================================
   CATEGORY BUTTONS
   ========================================================= */

.hapl-category {
    display: flex;

    align-items: center;

    justify-content: space-between;

    width: 100%;

    min-height: 48px;

    box-sizing: border-box;

    padding: 15px 14px;

    margin-bottom: 8px;

    border: 1px solid #e1e8f2;

    border-radius: 7px;

    color: #16376e;

    background: #fff;

    font-family: Arial, sans-serif;

    font-size: 15px;

    font-weight: 600;

    text-decoration: none;

    cursor: pointer;

    transition:
        background .2s ease,
        color .2s ease,
        border-color .2s ease,
        transform .2s ease,
        box-shadow .2s ease;
}

.hapl-category:last-child {
    margin-bottom: 0;
}

.hapl-category:hover,
.hapl-category.active {
    background: #0847a8;

    color: #fff;

    border-color: #0847a8;

    transform: translateX(2px);

    box-shadow:
        0 4px 12px rgba(8, 71, 168, 0.18);
}

.hapl-category:focus {
    outline: 2px solid #4da3ff;

    outline-offset: 2px;
}

.hapl-category-arrow {
    font-size: 19px;

    line-height: 1;
}


/* =========================================================
   RIGHT DOCUMENT PANEL
   ========================================================= */

.hapl-document-panel {
    background: #fff;

    border: 1px solid #e3eaf3;

    border-radius: 10px;

    padding: 21px;

    box-shadow:
        0 3px 14px rgba(25, 55, 95, 0.05);

    box-sizing: border-box;
}


/* =========================================================
   CATEGORY PANEL VISIBILITY
   ========================================================= */

.hapl-category-section {
    display: none;

    margin: 0;

    scroll-margin-top: 25px;
}

.hapl-category-section.is-visible {
    display: block;
}


/* =========================================================
   DOCUMENT HEADING
   ========================================================= */

.hapl-document-heading {
    margin-bottom: 18px;
}

.hapl-document-heading h2 {
    margin: 0 0 5px;

    color: #102b5c;

    font-size: 19px;

    font-weight: 700;
}

.hapl-document-heading p {
    margin: 0;

    color: #64748b;

    font-size: 14px;

    line-height: 1.5;
}


/* =========================================================
   SECTION LABEL
   ========================================================= */

.hapl-section-label {
    display: inline-block;

    margin-bottom: 7px;

    padding: 4px 9px;

    border-radius: 20px;

    background: #edf5ff;

    color: #075ca8;

    font-size: 11px;

    font-weight: 700;
}


/* =========================================================
   DOCUMENT GRID
   ========================================================= */

.hapl-document-grid {
    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 12px;
}


/* =========================================================
   DOCUMENT CARD
   ========================================================= */

.hapl-document {
    display: flex;

    align-items: center;

    gap: 12px;

    min-height: 92px;

    padding: 13px;

    box-sizing: border-box;

    border: 1px solid #e1e8f2;

    border-radius: 8px;

    background: #fff;

    text-decoration: none;

    transition:
        border-color .2s ease,
        box-shadow .2s ease,
        transform .2s ease;
}

.hapl-document:hover {
    border-color: #9dbce8;

    box-shadow:
        0 7px 18px rgba(20, 65, 125, 0.10);

    transform: translateY(-2px);
}

.hapl-icon {
    flex: 0 0 46px;

    width: 46px;

    height: 46px;

    border-radius: 11px;

    background: #edf4ff;

    color: #0649a8;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 20px;
}

.hapl-document-content {
    flex: 1;

    min-width: 0;
}

.hapl-document h3 {
    margin: 0 0 5px;

    color: #083d91;

    font-size: 13px;

    line-height: 1.3;

    font-weight: 700;
}

.hapl-document p {
    margin: 0;

    color: #66758a;

    font-size: 11.5px;

    line-height: 1.45;
}

.hapl-document-arrow {
    flex: 0 0 auto;

    color: #0649a8;

    font-size: 19px;

    line-height: 1;
}


/* =========================================================
   VIEW ALL
   ========================================================= */

.hapl-view-all {
    display: block;

    width: max-content;

    margin: 20px auto 0;

    padding: 10px 25px;

    border: 1px solid #78a7e7;

    border-radius: 7px;

    color: #0649a8;

    background: #fff;

    text-decoration: none;

    font-size: 13px;

    font-weight: 600;

    transition: all .2s ease;
}

.hapl-view-all:hover {
    background: #0649a8;

    color: #fff;
}


/* =========================================================
   =========================================================
   LATEST UPDATES
   =========================================================
   ========================================================= */

.hapl-latest {
    max-width: 1200px;

    margin: 0 auto 30px;

    padding: 20px 18px;

    box-sizing: border-box;
}

.hapl-latest-header {
    display: flex;

    align-items: center;

    justify-content: space-between;

    margin-bottom: 14px;
}

.hapl-latest-header h2 {
    margin: 0;

    color: #102b5c;

    font-size: 20px;

    font-weight: 700;
}

.hapl-latest-header a {
    color: #0649a8;

    text-decoration: none;

    font-size: 13px;

    font-weight: 600;
}

.hapl-latest-header a:hover {
    text-decoration: underline;
}


/* =========================================================
   LATEST UPDATE GRID
   ========================================================= */

.hapl-latest-grid {
    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 12px;
}


/* =========================================================
   UPDATE CARD
   ========================================================= */

.hapl-update {
    display: flex;

    align-items: center;

    min-height: 105px;

    background: #fff;

    border: 1px solid #e1e8f2;

    border-radius: 9px;

    overflow: hidden;

    text-decoration: none;

    box-shadow:
        0 3px 12px rgba(25, 55, 95, .04);

    transition:
        transform .2s ease,
        box-shadow .2s ease,
        border-color .2s ease;
}

.hapl-update:hover {
    transform: translateY(-2px);

    box-shadow:
        0 7px 18px rgba(20, 65, 125, .10);

    border-color: #a9c6ec;
}


/* =========================================================
   DATE
   ========================================================= */

.hapl-date {
    width: 57px;

    min-width: 57px;

    align-self: stretch;

    display: flex;

    flex-direction: column;

    justify-content: center;

    align-items: center;

    background: #f4f7fc;

    color: #0649a8;

    border-right: 1px solid #e5ebf4;
}

.hapl-date strong {
    font-size: 21px;

    line-height: 1;
}

.hapl-date span {
    margin-top: 4px;

    font-size: 10px;

    font-weight: 700;
}

.hapl-date small {
    margin-top: 2px;

    font-size: 9px;
}


/* =========================================================
   UPDATE ICONS
   ========================================================= */

.hapl-update-icon {
    width: 34px;

    height: 40px;

    min-width: 34px;

    margin: 0 9px;

    border-radius: 7px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 18px;
}

.hapl-pdf {
    background: #fff0f1;

    color: #e63946;
}

.hapl-green {
    background: #edf9f1;

    color: #269653;
}

.hapl-purple {
    background: #f3efff;

    color: #7048d8;
}

.hapl-blue {
    background: #edf5ff;

    color: #075ca8;
}


/* =========================================================
   UPDATE CONTENT
   ========================================================= */

.hapl-update-content {
    flex: 1;

    min-width: 0;
}

.hapl-update-content h3 {
    margin: 0 0 6px;

    color: #152f61;

    font-size: 12.5px;

    line-height: 1.35;

    font-weight: 700;
}

.hapl-update-content p {
    margin: 0;

    color: #738197;

    font-size: 10.5px;

    line-height: 1.35;
}


/* =========================================================
   UPDATE ACTION
   ========================================================= */

.hapl-download {
    padding: 0 12px 0 6px;

    color: #0649a8;

    font-size: 19px;

    font-weight: 600;

    line-height: 1;
}


/* =========================================================
   =========================================================
   NEW UPDATE TEMPLATE
   =========================================================
   =========================================================

   COPY THIS BLOCK WHEN ADDING A NEW UPDATE.

   STEPS:
   1. Copy the block.
   2. Paste BEFORE the current Update 1.
   3. Change date.
   4. Change title.
   5. Change category.
   6. Change URL.
   7. Use → for a page.
   8. Use ↓ for a direct PDF.

   ========================================================= */


/*
<a
    href="PASTE-PAGE-URL-HERE"
    class="hapl-update"
>

    <div class="hapl-date">

        <strong>
            DD
        </strong>

        <span>
            MON
        </span>

        <small>
            YYYY
        </small>

    </div>


    <div class="hapl-update-icon hapl-blue">
        ▤
    </div>


    <div class="hapl-update-content">

        <h3>
            UPDATE TITLE HERE
        </h3>

        <p>
            CATEGORY HERE
        </p>

    </div>


    <div class="hapl-download">
        →
    </div>

</a>
*/


/* =========================================================
   DIRECT PDF UPDATE TEMPLATE
   =========================================================

   Use when you have the actual PDF URL.

   Replace:
   PASTE-ACTUAL-PDF-URL-HERE

   ========================================================= */


/*
<a
    href="PASTE-ACTUAL-PDF-URL-HERE"
    class="hapl-update"
    target="_blank"
    rel="noopener"
>

    <div class="hapl-date">

        <strong>
            DD
        </strong>

        <span>
            MON
        </span>

        <small>
            YYYY
        </small>

    </div>


    <div class="hapl-update-icon hapl-pdf">
        ▤
    </div>


    <div class="hapl-update-content">

        <h3>
            DOCUMENT TITLE HERE
        </h3>

        <p>
            CATEGORY HERE
        </p>

    </div>


    <div class="hapl-download">
        ↓
    </div>

</a>
*/


/* =========================================================
   COMING SOON TEMPLATE
   =========================================================

   Use only when there is genuinely no document/page.

   IMPORTANT:
   - No "#"
   - No fake URL
   - No broken link

   ========================================================= */


/*
<div class="hapl-update">

    <div class="hapl-date">

        <strong>
            --
        </strong>

        <span>
            ---
        </span>

        <small>
            ----
        </small>

    </div>


    <div class="hapl-update-icon hapl-purple">
        ▤
    </div>


    <div class="hapl-update-content">

        <h3>
            DOCUMENT TITLE
        </h3>

        <p>
            CATEGORY · Coming Soon
        </p>

    </div>


    <div class="hapl-download">
        …
    </div>

</div>
*/


/* =========================================================
   STAY UPDATED
   ========================================================= */

.hapl-stay-updated {
    max-width: 1200px;

    margin: 20px auto 0;

    padding: 20px 24px;

    background:
        linear-gradient(
            90deg,
            #eef5ff,
            #f5f9ff
        );

    border: 1px solid #d9e7ff;

    border-radius: 10px;

    display: flex;

    align-items: center;

    gap: 18px;

    box-sizing: border-box;
}

.hapl-stay-icon {
    width: 46px;

    height: 46px;

    border-radius: 50%;

    background: #e4efff;

    color: #0645c7;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 22px;

    flex-shrink: 0;
}

.hapl-stay-content {
    flex: 1;

    min-width: 0;
}

.hapl-stay-content h3 {
    margin: 0 0 4px;

    color: #102b63;

    font-size: 17px;

    font-weight: 700;
}

.hapl-stay-content p {
    margin: 0;

    color: #243b63;

    font-size: 13px;

    line-height: 1.5;
}

.hapl-stay-button {
    display: inline-flex;

    align-items: center;

    gap: 8px;

    padding: 11px 22px;

    background: #062b73;

    color: #fff !important;

    border-radius: 6px;

    text-decoration: none !important;

    font-size: 13px;

    font-weight: 600;

    white-space: nowrap;

    transition: all .2s ease;
}

.hapl-stay-button:hover {
    background: #0645c7;

    transform: translateY(-1px);
}

.hapl-stay-button span {
    font-size: 17px;
}


/* =========================================================
   DESKTOP
   ========================================================= */

@media (min-width: 901px) {

    .hapl-dashboard-grid {
        grid-template-columns:
            290px
            minmax(0, 1fr);
    }

}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1000px) {

    .hapl-latest-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 900px) {

    .hapl-dashboard-grid {
        grid-template-columns: 1fr;
    }

    .hapl-document-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }

    .hapl-hero {
        padding: 45px 28px;
    }

    .hapl-hero h1 {
        font-size: 34px;
    }

}


@media (max-width: 600px) {

    .hapl-hero {
        min-height: 230px;

        padding: 38px 20px;
    }

    .hapl-hero h1 {
        font-size: 30px;
    }

    .hapl-hero p {
        font-size: 15px;
    }

    .hapl-dashboard {
        padding: 0 12px;
    }

    .hapl-category-panel,
    .hapl-document-panel {
        padding: 18px 14px;
    }

    .hapl-document-grid {
        grid-template-columns: 1fr;
    }

    .hapl-document {
        min-height: 88px;
    }

    .hapl-latest {
        padding: 15px 12px;
    }

    .hapl-latest-header h2 {
        font-size: 18px;
    }

    .hapl-latest-grid {
        grid-template-columns: 1fr;
    }

    .hapl-stay-updated {
        flex-wrap: wrap;

        padding: 18px;
    }

    .hapl-stay-button {
        width: 100%;

        justify-content: center;
    }

}

</style>


<!-- =========================================================
     INVESTOR INFORMATION
     ========================================================= -->

<div class="hapl-investor">


    <!-- =====================================================
         HERO
         ===================================================== -->

    <section class="hapl-hero">

        <div class="hapl-hero-inner">

            <div class="hapl-accent"></div>

            <h1>
                Investor Information
            </h1>

            <p>
                Explore financial performance, regulatory filings,
                shareholder information and corporate governance.
            </p>

        </div>

    </section>


    <!-- =====================================================
         CATEGORY DASHBOARD
         ===================================================== -->

    <section class="hapl-dashboard">

        <div class="hapl-dashboard-grid">


            <!-- =================================================
                 LEFT CATEGORY MENU
                 ================================================= -->

            <div class="hapl-category-panel">

                <h2>
                    Explore By Category
                </h2>


                <!-- FINANCIAL & REGULATORY -->

                <a
                    href="#"
                    class="hapl-category active"
                    data-category="financial"
                    aria-controls="financial"
                    aria-selected="true"
                >

                    <span>
                        Financial &amp; Regulatory
                    </span>

                    <span class="hapl-category-arrow">
                        ›
                    </span>

                </a>


                <!-- SHAREHOLDERS -->

                <a
                    href="#"
                    class="hapl-category"
                    data-category="shareholders"
                    aria-controls="shareholders"
                    aria-selected="false"
                >

                    <span>
                        Shareholders
                    </span>

                    <span class="hapl-category-arrow">
                        ›
                    </span>

                </a>


                <!-- CORPORATE GOVERNANCE -->

                <a
                    href="#"
                    class="hapl-category"
                    data-category="governance"
                    aria-controls="governance"
                    aria-selected="false"
                >

                    <span>
                        Corporate Governance
                    </span>

                    <span class="hapl-category-arrow">
                        ›
                    </span>

                </a>


                <!-- ANNOUNCEMENTS -->

                <a
                    href="#"
                    class="hapl-category"
                    data-category="announcements"
                    aria-controls="announcements"
                    aria-selected="false"
                >

                    <span>
                        Announcements
                    </span>

                    <span class="hapl-category-arrow">
                        ›
                    </span>

                </a>


                <!-- INVESTOR SERVICES -->

                <a
                    href="#"
                    class="hapl-category"
                    data-category="services"
                    aria-controls="services"
                    aria-selected="false"
                >

                    <span>
                        Investor Services
                    </span>

                    <span class="hapl-category-arrow">
                        ›
                    </span>

                </a>

            </div>


            <!-- =================================================
                 RIGHT SIDE
                 ================================================= -->

            <div>


                <!-- =================================================
                     1. FINANCIAL & REGULATORY
                     ================================================= -->

                <div
                    class="hapl-document-panel hapl-category-section is-visible"
                    id="financial"
                >

                    <div class="hapl-document-heading">

                        <span class="hapl-section-label">
                            FINANCIAL &amp; REGULATORY
                        </span>

                        <h2>
                            Financial &amp; Regulatory
