   BREADCRUMB
   ========================================================= */

.hapl-ar-breadcrumb {
    max-width: 1200px;
    margin: 0 auto;
    padding: 18px 0;
    font-size: 14px;
    color: #526a8d;
}

.hapl-ar-breadcrumb a {
    color: #0564b8;
    text-decoration: none;
}

.hapl-ar-breadcrumb a:hover {
    text-decoration: underline;
}

/* =========================================================
   CONTENT
   ========================================================= */

.hapl-ar-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 0 40px;
}

.hapl-ar-panel {
    background: #fff;
    border: 1px solid #dce7f5;
    border-radius: 12px;
    padding: 28px;
    box-shadow: 0 4px 18px rgba(20, 65, 110, 0.07);
}

.hapl-ar-panel h2 {
    margin: 0 0 8px;
    color: #0b356d;
    font-size: 28px;
    font-weight: 700;
}

.hapl-ar-intro {
    margin: 0 0 28px;
    color: #607795;
    font-size: 15px;
    line-height: 1.7;
}

/* =========================================================
   CURRENT YEAR
   ========================================================= */

.hapl-ar-current {
    margin-bottom: 30px;
    padding: 20px;
    border: 1px solid #b8d6f7;
    border-radius: 12px;
    background: linear-gradient(
        90deg,
        #f3f8ff 0%,
        #ffffff 100%
    );
}

.hapl-ar-current-label {
    display: inline-block;
    margin-bottom: 14px;
    padding: 5px 10px;
    border-radius: 20px;
    background: #e5f1ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
}

/* =========================================================
   YEAR HEADER
   ========================================================= */

.hapl-ar-year {
    margin-bottom: 18px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    overflow: hidden;
}

.hapl-ar-year summary {
    list-style: none;
    cursor: pointer;
    padding: 18px 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    color: #102f60;
    font-size: 20px;
    font-weight: 700;
    transition: background 0.2s ease;
}

.hapl-ar-year summary::-webkit-details-marker {
    display: none;
}

.hapl-ar-year summary:hover {
    background: #f7fbff;
}

.hapl-ar-year summary::after {
    content: "+";
    width: 28px;
    height: 28px;
    flex: 0 0 28px;
    border: 1px solid #b9d3ef;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075ca8;
    font-size: 20px;
    font-weight: 400;
    line-height: 1;
}

.hapl-ar-year[open] summary::after {
    content: "−";
}

.hapl-ar-year[open] summary {
    border-bottom: 1px solid #dce7f5;
    background: #f8fbff;
}

.hapl-ar-year-content {
    padding: 18px 20px 20px;
}

/* =========================================================
   YEAR BADGE
   ========================================================= */

.hapl-ar-badge {
    display: inline-block;
    margin-left: 8px;
    padding: 5px 10px;
    border-radius: 20px;
    background: #eaf3ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
    vertical-align: middle;
}

/* =========================================================
   DOCUMENT CARD
   ========================================================= */

.hapl-ar-document {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 18px;
    margin-bottom: 12px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    transition: all 0.25s ease;
    box-sizing: border-box;
}

.hapl-ar-document:last-child {
    margin-bottom: 0;
}

.hapl-ar-document:hover {
    border-color: #9fc8f5;
    box-shadow: 0 7px 18px rgba(20, 65, 110, 0.09);
    transform: translateY(-2px);
}

/* =========================================================
   DOCUMENT ICON
   ========================================================= */

.hapl-ar-icon {
    width: 50px;
    height: 50px;
    flex: 0 0 50px;
    border-radius: 12px;
    background: #edf5ff;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075ca8;
    font-size: 24px;
}

/* =========================================================
   DOCUMENT INFO
   ========================================================= */

.hapl-ar-document-info {
    flex: 1;
    min-width: 0;
}

.hapl-ar-document-info h4 {
    margin: 0 0 6px;
    color: #103d79;
    font-size: 16px;
    font-weight: 700;
}

.hapl-ar-document-info p {
    margin: 0;
    color: #687d99;
    font-size: 13px;
    line-height: 1.55;
}

/* =========================================================
   ACTION BUTTON
   ========================================================= */

.hapl-ar-action {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 110px;
    padding: 9px 14px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    box-sizing: border-box;
    transition: all 0.2s ease;
}

.hapl-ar-action:hover {
    background: #075ca8;
    color: #fff;
    border-color: #075ca8;
}

.hapl-ar-action.pending {
    border-color: #d7e2ef;
    background: #f5f8fc;
    color: #71839a;
    cursor: default;
}

.hapl-ar-action.pending:hover {
    background: #f5f8fc;
    color: #71839a;
    border-color: #d7e2ef;
}

/* =========================================================
   INFORMATION NOTE
   ========================================================= */

.hapl-ar-note {
    margin-top: 26px;
    padding: 18px 20px;
    background: linear-gradient(
        90deg,
        #eef6ff,
        #f7fbff
    );
    border: 1px solid #d8e8fb;
    border-radius: 10px;
}

.hapl-ar-note h4 {
    margin: 0 0 6px;
    color: #123b70;
    font-size: 15px;
}

.hapl-ar-note p {
    margin: 0;
    color: #627894;
    font-size: 13px;
    line-height: 1.6;
}

/* =========================================================
   BACK BUTTON
   ========================================================= */

.hapl-ar-back {
    display: inline-flex;
    align-items: center;
    margin-top: 28px;
    padding: 10px 18px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    transition: all 0.2s ease;
}

.hapl-ar-back:hover {
    background: #075ca8;
    color: #fff;
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 900px) {

    .hapl-ar-hero {
        padding: 45px 25px;
    }

    .hapl-ar-hero h1 {
        font-size: 32px;
    }

    .hapl-ar-breadcrumb,
    .hapl-ar-content {
        padding-left: 20px;
        padding-right: 20px;
    }

}

@media (max-width: 600px) {

    .hapl-ar-hero {
        padding: 38px 20px;
    }

    .hapl-ar-hero h1 {
        font-size: 29px;
    }

    .hapl-ar-hero p {
        font-size: 15px;
    }

    .hapl-ar-panel {
        padding: 20px;
    }

    .hapl-ar-panel h2 {
        font-size: 23px;
    }

    .hapl-ar-year summary {
        padding: 16px;
        font-size: 17px;
    }

    .hapl-ar-year-content {
        padding: 15px;
    }

    .hapl-ar-document {
        align-items: flex-start;
        flex-wrap: wrap;
        padding: 16px;
    }

    .hapl-ar-document-info {
        flex: 1 1 calc(100% - 70px);
    }

    .hapl-ar-action {
        margin-left: 66px;
        width: calc(100% - 66px);
    }

    .hapl-ar-breadcrumb {
        padding-top: 15px;
        padding-bottom: 15px;
        font-size: 13px;
    }
}
</style>


