/* =========================================================
   HAPL - SHAREHOLDING PATTERNS
   ========================================================= */

.hapl-sp {
    font-family: Arial, sans-serif;
    color: #132b52;
    background: #f7faff;
}

/* =========================================================
   HERO
   ========================================================= */

.hapl-sp-hero {
    background: linear-gradient(
        110deg,
        #062b63 0%,
        #0b438c 55%,
        #075ca8 100%
    );
    color: #fff;
    padding: 55px 50px;
}

.hapl-sp-hero-inner {
    max-width: 1200px;
    margin: 0 auto;
}

.hapl-sp-accent {
    width: 38px;
    height: 4px;
    background: #4da3ff;
    margin-bottom: 18px;
}

.hapl-sp-hero h1 {
    margin: 0 0 12px;
    color: #fff;
    font-size: 40px;
    font-weight: 700;
    line-height: 1.2;
}

.hapl-sp-hero p {
    max-width: 760px;
    margin: 0;
    color: #eef6ff;
    font-size: 17px;
    line-height: 1.7;
}

/* =========================================================
   BREADCRUMB
   ========================================================= */

.hapl-sp-breadcrumb {
    max-width: 1200px;
    margin: 0 auto;
    padding: 18px 0;
    font-size: 14px;
    color: #526a8d;
}

.hapl-sp-breadcrumb a {
    color: #0564b8;
    text-decoration: none;
}

.hapl-sp-breadcrumb a:hover {
    text-decoration: underline;
}

/* =========================================================
   CONTENT
   ========================================================= */

.hapl-sp-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 0 40px;
}

.hapl-sp-panel {
    background: #fff;
    border: 1px solid #dce7f5;
    border-radius: 12px;
    padding: 28px;
    box-shadow: 0 4px 18px rgba(20, 65, 110, 0.07);
}

.hapl-sp-panel h2 {
    margin: 0 0 8px;
    color: #0b356d;
    font-size: 28px;
}

.hapl-sp-intro {
    margin: 0 0 28px;
    color: #607795;
    font-size: 15px;
    line-height: 1.7;
}

/* =========================================================
   CURRENT YEAR
   ========================================================= */

.hapl-sp-current-year {
    margin-bottom: 30px;
    padding: 20px;
    background: #f8fbff;
    border: 1px solid #cfe1f7;
    border-radius: 12px;
}

.hapl-sp-current-label {
    display: inline-flex;
    align-items: center;
    padding: 5px 11px;
    margin-bottom: 12px;
    border-radius: 20px;
    background: #e5f1ff;
    color: #075ca8;
    font-size: 12px;
    font-weight: 700;
}

/* =========================================================
   YEAR HEADING
   ========================================================= */

.hapl-sp-year-heading {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
}

.hapl-sp-year-heading h3 {
    margin: 0;
    color: #102f60;
    font-size: 21px;
}

.hapl-sp-badge {
    padding: 5px 10px;
    border-radius: 20px;
    background: #eaf3ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
}

/* =========================================================
   COLLAPSIBLE HISTORICAL YEARS
   ========================================================= */

.hapl-sp-history {
    margin-bottom: 14px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    overflow: hidden;
}

.hapl-sp-history summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 18px 20px;
    cursor: pointer;
    list-style: none;
    color: #102f60;
    font-size: 19px;
    font-weight: 700;
    background: #fff;
    transition: all .2s ease;
}

.hapl-sp-history summary::-webkit-details-marker {
    display: none;
}

.hapl-sp-history summary::after {
    content: "＋";
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: #edf5ff;
    color: #075ca8;
    font-size: 18px;
    font-weight: 400;
}

.hapl-sp-history[open] summary {
    background: #f7fbff;
    border-bottom: 1px solid #dce7f5;
}

.hapl-sp-history[open] summary::after {
    content: "−";
}

.hapl-sp-history summary:hover {
    background: #f7fbff;
}

.hapl-sp-history-content {
    padding: 18px 20px 20px;
}

/* =========================================================
   DOCUMENTS
   ========================================================= */

.hapl-sp-document {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 20px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    transition: all .25s ease;
}

.hapl-sp-document + .hapl-sp-document {
    margin-top: 12px;
}

.hapl-sp-document:hover {
    border-color: #9fc8f5;
    box-shadow: 0 7px 18px rgba(20, 65, 110, .09);
    transform: translateY(-2px);
}

.hapl-sp-icon {
    width: 50px;
    height: 50px;
    flex: 0 0 50px;
    border-radius: 12px;
    background: #edf5ff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
}

.hapl-sp-info {
    flex: 1;
    min-width: 0;
}

.hapl-sp-info h4 {
    margin: 0 0 6px;
    color: #103d79;
    font-size: 16px;
}

.hapl-sp-info p {
    margin: 0;
    color: #687d99;
    font-size: 13px;
    line-height: 1.55;
}

/* =========================================================
   PDF BUTTON
   ========================================================= */

.hapl-sp-action {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 125px;
    padding: 9px 15px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    font-size: 13px;
    font-weight: 600;
    text-align: center;
    text-decoration: none;
    box-sizing: border-box;
    transition: all .2s ease;
}

.hapl-sp-action:hover {
    background: #075ca8;
    color: #fff;
    border-color: #075ca8;
    text-decoration: none;
}

/* Pending document */

.hapl-sp-action.pending {
    border-color: #d7e2ef;
    background: #f5f8fc;
    color: #70839d;
    cursor: default;
    pointer-events: none;
}

/* =========================================================
   INFORMATION BOX
   ========================================================= */

.hapl-sp-note {
    margin-top: 22px;
    padding: 18px 20px;
    background: linear-gradient(
        90deg,
        #eef6ff,
        #f7fbff
    );
    border: 1px solid #d8e8fb;
    border-radius: 10px;
}

.hapl-sp-note h4 {
    margin: 0 0 6px;
    color: #123b70;
    font-size: 15px;
}

.hapl-sp-note p {
    margin: 0;
    color: #627894;
    font-size: 13px;
    line-height: 1.6;
}

/* =========================================================
   BACK BUTTON
   ========================================================= */

.hapl-sp-back {
    display: inline-flex;
    margin-top: 28px;
    padding: 10px 18px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    transition: all .2s ease;
}

.hapl-sp-back:hover {
    background: #075ca8;
    color: #fff;
    border-color: #075ca8;
}

/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

    .hapl-sp-hero {
        padding: 45px 25px;
    }

    .hapl-sp-hero h1 {
        font-size: 32px;
    }

    .hapl-sp-breadcrumb,
    .hapl-sp-content {
        padding-left: 20px;
        padding-right: 20px;
    }
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 600px) {

    .hapl-sp-hero {
        padding: 38px 20px;
    }

    .hapl-sp-hero h1 {
        font-size: 29px;
    }

    .hapl-sp-hero p {
        font-size: 15px;
    }

    .hapl-sp-panel {
        padding: 20px;
    }

    .hapl-sp-panel h2 {
        font-size: 23px;
    }

    .hapl-sp-year-heading {
        align-items: flex-start;
        flex-wrap: wrap;
    }

    .hapl-sp-document {
        align-items: flex-start;
        flex-wrap: wrap;
        gap: 12px;
        padding: 16px;
    }

    .hapl-sp-icon {
        width: 44px;
        height: 44px;
        flex-basis: 44px;
        font-size: 21px;
    }

    .hapl-sp-info {
        flex: 1 1 calc(100% - 60px);
    }

    .hapl-sp-action {
        width: 100%;
        margin-top: 4px;
    }

    .hapl-sp-history summary {
        padding: 16px;
        font-size: 17px;
    }

    .hapl-sp-history-content {
        padding: 15px;
    }
}
</style>


