/* =========================================================
   HAPL - REGULATORY FILINGS
   ========================================================= */

.hapl-rf {
    font-family: Arial, sans-serif;
    color: #132b52;
    background: #f7faff;
}

/* =========================================================
   HERO
   ========================================================= */

.hapl-rf-hero {
    position: relative;
    overflow: hidden;
    background: linear-gradient(
        110deg,
        #062b63 0%,
        #0b438c 55%,
        #075ca8 100%
    );
    color: #fff;
    padding: 55px 50px;
}

.hapl-rf-hero-inner {
    max-width: 1200px;
    margin: 0 auto;
}

.hapl-rf-accent {
    width: 38px;
    height: 4px;
    background: #4da3ff;
    margin-bottom: 18px;
}

.hapl-rf-hero h1 {
    margin: 0 0 12px;
    color: #fff;
    font-size: 40px;
    font-weight: 700;
    line-height: 1.2;
}

.hapl-rf-hero p {
    max-width: 780px;
    margin: 0;
    color: #eef6ff;
    font-size: 17px;
    line-height: 1.7;
}

/* =========================================================
   BREADCRUMB
   ========================================================= */

.hapl-rf-breadcrumb {
    max-width: 1200px;
    margin: 0 auto;
    padding: 18px 0;
    font-size: 14px;
    color: #526a8d;
}

.hapl-rf-breadcrumb a {
    color: #0564b8;
    text-decoration: none;
}

.hapl-rf-breadcrumb a:hover {
    text-decoration: underline;
}

/* =========================================================
   CONTENT
   ========================================================= */

.hapl-rf-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 0 40px;
}

.hapl-rf-panel {
    background: #fff;
    border: 1px solid #dce7f5;
    border-radius: 12px;
    padding: 28px;
    box-shadow: 0 4px 18px rgba(20, 65, 110, 0.07);
}

.hapl-rf-panel h2 {
    margin: 0 0 8px;
    color: #0b356d;
    font-size: 28px;
    font-weight: 700;
}

.hapl-rf-intro {
    margin: 0 0 28px;
    color: #607795;
    font-size: 15px;
    line-height: 1.7;
}

/* =========================================================
   CURRENT YEAR
   ========================================================= */

.hapl-rf-current {
    margin-bottom: 30px;
    padding: 20px;
    border: 1px solid #b8d6f7;
    border-radius: 12px;
    background: linear-gradient(
        90deg,
        #f3f8ff 0%,
        #ffffff 100%
    );
}

.hapl-rf-current-label {
    display: inline-block;
    margin-bottom: 14px;
    padding: 5px 10px;
    border-radius: 20px;
    background: #e5f1ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
}

/* =========================================================
   YEAR ACCORDION
   ========================================================= */

.hapl-rf-year {
    margin-bottom: 18px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    overflow: hidden;
}

.hapl-rf-year summary {
    list-style: none;
    cursor: pointer;
    padding: 18px 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    color: #102f60;
    font-size: 20px;
    font-weight: 700;
    transition: background 0.2s ease;
}

.hapl-rf-year summary::-webkit-details-marker {
    display: none;
}

.hapl-rf-year summary:hover {
    background: #f7fbff;
}

.hapl-rf-year summary::after {
    content: "+";
    width: 28px;
    height: 28px;
    flex: 0 0 28px;
    border: 1px solid #b9d3ef;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075ca8;
    font-size: 20px;
    font-weight: 400;
    line-height: 1;
}

.hapl-rf-year[open] summary::after {
    content: "−";
}

.hapl-rf-year[open] summary {
    border-bottom: 1px solid #dce7f5;
    background: #f8fbff;
}

.hapl-rf-year-content {
    padding: 18px 20px 20px;
}

/* =========================================================
   YEAR BADGE
   ========================================================= */

.hapl-rf-badge {
    display: inline-block;
    margin-left: 8px;
    padding: 5px 10px;
    border-radius: 20px;
    background: #eaf3ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
    vertical-align: middle;
}

/* =========================================================
   DOCUMENT CARD
   ========================================================= */

.hapl-rf-document {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 18px;
    margin-bottom: 12px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    transition: all 0.25s ease;
    box-sizing: border-box;
}

.hapl-rf-document:last-child {
    margin-bottom: 0;
}

.hapl-rf-document:hover {
