/* =========================================================
   HAPL - BOARD MEETINGS
   ========================================================= */

.hapl-bm {
    font-family: Arial, sans-serif;
    color: #132b52;
    background: #f7faff;
}

/* =========================================================
   HERO
   ========================================================= */

.hapl-bm-hero {
    position: relative;
    overflow: hidden;
    background: linear-gradient(
        110deg,
        #062b63 0%,
        #0b438c 55%,
        #075ca8 100%
    );
    color: #fff;
    padding: 55px 50px;
}

.hapl-bm-hero-inner {
    max-width: 1200px;
    margin: 0 auto;
}

.hapl-bm-accent {
    width: 38px;
    height: 4px;
    background: #4da3ff;
    margin-bottom: 18px;
}

.hapl-bm-hero h1 {
    margin: 0 0 12px;
    color: #fff;
    font-size: 40px;
    font-weight: 700;
    line-height: 1.2;
}

.hapl-bm-hero p {
    max-width: 780px;
    margin: 0;
    color: #eef6ff;
    font-size: 17px;
    line-height: 1.7;
}

/* =========================================================
   BREADCRUMB
   ========================================================= */

.hapl-bm-breadcrumb {
    max-width: 1200px;
    margin: 0 auto;
    padding: 18px 0;
    font-size: 14px;
    color: #526a8d;
}

.hapl-bm-breadcrumb a {
    color: #0564b8;
    text-decoration: none;
}

.hapl-bm-breadcrumb a:hover {
    text-decoration: underline;
}

/* =========================================================
   CONTENT
   ========================================================= */

.hapl-bm-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 0 40px;
}

.hapl-bm-panel {
    background: #fff;
    border: 1px solid #dce7f5;
    border-radius: 12px;
    padding: 28px;
    box-shadow: 0 4px 18px rgba(20, 65, 110, 0.07);
}

.hapl-bm-panel h2 {
    margin: 0 0 8px;
    color: #0b356d;
    font-size: 28px;
    font-weight: 700;
}

.hapl-bm-intro {
    margin: 0 0 28px;
    color: #607795;
    font-size: 15px;
    line-height: 1.7;
}

/* =========================================================
   CURRENT YEAR
   ========================================================= */

.hapl-bm-current {
    margin-bottom: 30px;
    padding: 20px;
    border: 1px solid #b8d6f7;
    border-radius: 12px;
    background: linear-gradient(
        90deg,
        #f3f8ff 0%,
        #ffffff 100%
    );
}

.hapl-bm-current-label {
    display: inline-block;
    margin-bottom: 14px;
    padding: 5px 10px;
    border-radius: 20px;
    background: #e5f1ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
}

/* =========================================================
   YEAR ACCORDION
   ========================================================= */

.hapl-bm-year {
    margin-bottom: 18px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    overflow: hidden;
}

.hapl-bm-year summary {
    list-style: none;
    cursor: pointer;
    padding: 18px 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    color: #102f60;
    font-size: 20px;
    font-weight: 700;
    transition: background 0.2s ease;
}

.hapl-bm-year summary::-webkit-details-marker {
    display: none;
}

.hapl-bm-year summary:hover {
    background: #f7fbff;
}

.hapl-bm-year summary::after {
    content: "+";
    width: 28px;
    height: 28px;
    flex: 0 0 28px;
    border: 1px solid #b9d3ef;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075ca8;
    font-size: 20px;
    font-weight: 400;
    line-height: 1;
}

.hapl-bm-year[open] summary::after {
    content: "−";
}

.hapl-bm-year[open] summary {
    border-bottom: 1px solid #dce7f5;
    background: #f8fbff;
}

.hapl-bm-year-content {
    padding: 18px 20px 20px;
}

/* =========================================================
   BADGE
   ========================================================= */

.hapl-bm-badge {
    display: inline-block;
    margin-left: 8px;
    padding: 5px 10px;
    border-radius: 20px;
    background: #eaf3ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
    vertical-align: middle;
}

/* =========================================================
   SECTION TITLE
   ========================================================= */

.hapl-bm-section-title {
    margin: 0 0 12px;
    color: #123b70;
    font-size: 18px;
    font-weight: 700;
}

/* =========================================================
   DOCUMENT CARD
   ========================================================= */

.hapl-bm-document {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 18px;
    margin-bottom: 12px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    transition: all 0.25s ease;
    box-sizing: border-box;
}

.hapl-bm-document:last-child {
    margin-bottom: 0;
}

.hapl-bm-document:hover {
    border-color: #9fc8f5;
    box-shadow: 0 7px 18px rgba(20, 65, 110, 0.09);
    transform: translateY(-2px);
}

/* =========================================================
   ICON
   ========================================================= */

.hapl-bm-icon {
    width: 50px;
    height: 50px;
    flex: 0 0 50px;
    border-radius: 12px;
    background: #edf5ff;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075ca8;
    font-size: 24px;
}

/* =========================================================
   DOCUMENT INFO
   ========================================================= */

.hapl-bm-document-info {
    flex: 1;
    min-width: 0;
}

.hapl-bm-document-info h4 {
    margin: 0 0 6px;
    color: #103d79;
    font-size: 16px;
    font-weight: 700;
}

.hapl-bm-document-info p {
    margin: 0;
    color: #687d99;
    font-size: 13px;
    line-height: 1.55;
}

/* =========================================================
   ACTION BUTTON
   ========================================================= */

.hapl-bm-action {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 110px;
    padding: 9px 14px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    box-sizing: border-box;
    transition: all 0.2s ease;
}

.hapl-bm-action:hover {
    background: #075ca8;
    color: #fff;
    border-color: #075ca8;
}

.hapl-bm-action.pending {
    border-color: #d7e2ef;
    background: #f5f8fc;
    color: #71839a;
    cursor: default;
}

.hapl-bm-action.pending:hover {
    background: #f5f8fc;
    color: #71839a;
    border-color: #d7e2ef;
}

/* =========================================================
   INFORMATION NOTE
   ========================================================= */

.hapl-bm-note {
    margin-top: 26px;
    padding: 18px 20px;
    background: linear-gradient(
        90deg,
        #eef6ff,
        #f7fbff
    );
    border: 1px solid #d8e8fb;
    border-radius: 10px;
}

.hapl-bm-note h4 {
    margin: 0 0 6px;
    color: #123b70;
    font-size: 15px;
}

.hapl-bm-note p {
    margin: 0;
    color: #627894;
    font-size: 13px;
    line-height: 1.6;
}

/* =========================================================
   BACK BUTTON
   ========================================================= */

.hapl-bm-back {
    display: inline-flex;
    align-items: center;
    margin-top: 28px;
    padding: 10px 18px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    transition: all 0.2s ease;
}

.hapl-bm-back:hover {
    background: #075ca8;
    color: #fff;
    border-color: #075ca8;
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 900px) {

    .hapl-bm-hero {
        padding: 45px 25px;
    }

    .hapl-bm-hero h1 {
        font-size: 32px;
    }

    .hapl-bm-breadcrumb,
    .hapl-bm-content {
        padding-left: 20px;
        padding-right: 20px;
    }
}

@media (max-width: 600px) {

    .hapl-bm-hero {
        padding: 38px 20px;
    }

    .hapl-bm-hero h1 {
        font-size: 29px;
    }

    .hapl-bm-hero p {
        font-size: 15px;
    }

    .hapl-bm-panel {
        padding: 20px;
    }

    .hapl-bm-panel h2 {
        font-size: 23px;
    }

    .hapl-bm-year summary {
        padding: 16px;
        font-size: 17px;
    }

    .hapl-bm-year-content {
        padding: 15px;
    }

    .hapl-bm-document {
        align-items: flex-start;
        flex-wrap: wrap;
        padding: 16px;
    }

    .hapl-bm-document-info {
        flex: 1 1 calc(100% - 70px);
    }

    .hapl-bm-action {
        margin-left: 66px;
        width: calc(100% - 66px);
    }

    .hapl-bm-breadcrumb {
        padding-top: 15px;
        padding-bottom: 15px;
        font-size: 13px;
    }
}
</style>


<div class="hapl-bm">

    <!-- =====================================================
         HERO
         ===================================================== -->

    <section class="hapl-bm-hero">

        <div class="hapl-bm-hero-inner">

            <div class="hapl-bm-accent"></div>

            <h1>Board Meetings</h1>

