/* =========================================================
   HAPL - CORPORATE ANNOUNCEMENTS
   ========================================================= */

.hapl-ca {
    font-family: Arial, sans-serif;
    color: #132b52;
    background: #f7faff;
}

/* =========================================================
   HERO
   ========================================================= */

.hapl-ca-hero {
    position: relative;
    overflow: hidden;
    background: linear-gradient(
        110deg,
        #062b63 0%,
        #0b438c 55%,
        #075ca8 100%
    );
    color: #fff;
    padding: 55px 50px;
}

.hapl-ca-hero-inner {
    max-width: 1200px;
    margin: 0 auto;
}

.hapl-ca-accent {
    width: 38px;
    height: 4px;
    background: #4da3ff;
    margin-bottom: 18px;
}

.hapl-ca-hero h1 {
    margin: 0 0 12px;
    color: #fff;
    font-size: 40px;
    font-weight: 700;
    line-height: 1.2;
}

.hapl-ca-hero p {
    max-width: 800px;
    margin: 0;
    color: #eef6ff;
    font-size: 17px;
    line-height: 1.7;
}

/* =========================================================
   BREADCRUMB
   ========================================================= */

.hapl-ca-breadcrumb {
    max-width: 1200px;
    margin: 0 auto;
    padding: 18px 0;
    font-size: 14px;
    color: #526a8d;
}

.hapl-ca-breadcrumb a {
    color: #0564b8;
    text-decoration: none;
}

.hapl-ca-breadcrumb a:hover {
    text-decoration: underline;
}

/* =========================================================
   CONTENT
   ========================================================= */

.hapl-ca-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 0 40px;
}

.hapl-ca-panel {
    background: #fff;
    border: 1px solid #dce7f5;
    border-radius: 12px;
    padding: 28px;
    box-shadow: 0 4px 18px rgba(20, 65, 110, 0.07);
}

.hapl-ca-panel h2 {
    margin: 0 0 8px;
    color: #0b356d;
    font-size: 28px;
    font-weight: 700;
}

.hapl-ca-intro {
    margin: 0 0 28px;
    color: #607795;
    font-size: 15px;
    line-height: 1.7;
}

/* =========================================================
   CURRENT YEAR
   ========================================================= */

.hapl-ca-current {
    margin-bottom: 30px;
    padding: 20px;
    border: 1px solid #b8d6f7;
    border-radius: 12px;
    background: linear-gradient(
        90deg,
        #f3f8ff 0%,
        #ffffff 100%
    );
}

.hapl-ca-current-label {
    display: inline-block;
    margin-bottom: 14px;
    padding: 5px 10px;
    border-radius: 20px;
    background: #e5f1ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
}

/* =========================================================
   YEAR ACCORDION
   ========================================================= */

.hapl-ca-year {
    margin-bottom: 18px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    overflow: hidden;
}

.hapl-ca-year summary {
    list-style: none;
    cursor: pointer;
    padding: 18px 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    color: #102f60;
    font-size: 20px;
    font-weight: 700;
    transition: background 0.2s ease;
}

.hapl-ca-year summary::-webkit-details-marker {
    display: none;
}

.hapl-ca-year summary:hover {
    background: #f7fbff;
}

.hapl-ca-year summary::after {
    content: "+";
    width: 28px;
    height: 28px;
    flex: 0 0 28px;
    border: 1px solid #b9d3ef;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075ca8;
    font-size: 20px;
    font-weight: 400;
    line-height: 1;
}

.hapl-ca-year[open] summary::after {
    content: "−";
}

.hapl-ca-year[open] summary {
    border-bottom: 1px solid #dce7f5;
    background: #f8fbff;
}

.hapl-ca-year-content {
    padding: 18px 20px 20px;
}

/* =========================================================
   BADGE
   ========================================================= */

.hapl-ca-badge {
    display: inline-block;
    margin-left: 8px;
    padding: 5px 10px;
    border-radius: 20px;
    background: #eaf3ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
    vertical-align: middle;
}

/* =========================================================
   ANNOUNCEMENT CARD
   ========================================================= */

.hapl-ca-item {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 18px;
    margin-bottom: 12px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    transition: all 0.25s ease;
    box-sizing: border-box;
}

.hapl-ca-item:last-child {
    margin-bottom: 0;
}

.hapl-ca-item:hover {
    border-color: #9fc8f5;
    box-shadow: 0 7px 18px rgba(20, 65, 110, 0.09);
    transform: translateY(-2px);
}

/* =========================================================
   DATE
   ========================================================= */

.hapl-ca-date {
    width: 62px;
    height: 62px;
    flex: 0 0 62px;
    border-radius: 12px;
    background: #edf5ff;
    color: #075ca8;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
}

.hapl-ca-date-day {
    font-size: 20px;
    font-weight: 700;
    line-height: 1;
}

.hapl-ca-date-month {
    margin-top: 5px;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .5px;
}

/* =========================================================
   ANNOUNCEMENT INFO
   ========================================================= */

.hapl-ca-info {
    flex: 1;
    min-width: 0;
}

.hapl-ca-info h4 {
    margin: 0 0 6px;
    color: #103d79;
    font-size: 16px;
    font-weight: 700;
}

.hapl-ca-info p {
    margin: 0;
    color: #687d99;
    font-size: 13px;
    line-height: 1.55;
}

/* =========================================================
   ACTION
   ========================================================= */

.hapl-ca-action {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 110px;
    padding: 9px 14px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    box-sizing: border-box;
    transition: all 0.2s ease;
}

.hapl-ca-action:hover {
    background: #075ca8;
    color: #fff;
    border-color: #075ca8;
}

.hapl-ca-action.pending {
    border-color: #d7e2ef;
    background: #f5f8fc;
    color: #71839a;
    cursor: default;
}

.hapl-ca-action.pending:hover {
    background: #f5f8fc;
    color: #71839a;
    border-color: #d7e2ef;
}

/* =========================================================
   INFORMATION NOTE
   ========================================================= */

.hapl-ca-note {
    margin-top: 26px;
    padding: 18px 20px;
    background: linear-gradient(
        90deg,
        #eef6ff,
        #f7fbff
    );
    border: 1px solid #d8e8fb;
    border-radius: 10px;
}

.hapl-ca-note h4 {
    margin: 0 0 6px;
    color: #123b70;
    font-size: 15px;
}

.hapl-ca-note p {
    margin: 0;
    color: #627894;
    font-size: 13px;
    line-height: 1.6;
}

/* =========================================================
   BACK BUTTON
   ========================================================= */

.hapl-ca-back {
    display: inline-flex;
    align-items: center;
    margin-top: 28px;
    padding: 10px 18px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    transition: all 0.2s ease;
}

.hapl-ca-back:hover {
    background: #075ca8;
    color: #fff;
    border-color: #075ca8;
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 900px) {

    .hapl-ca-hero {
        padding: 45px 25px;
    }

    .hapl-ca-hero h1 {
        font-size: 32px;
    }

    .hapl-ca-breadcrumb,
    .hapl-ca-content {
        padding-left: 20px;
        padding-right: 20px;
    }
}

@media (max-width: 600px) {

    .hapl-ca-hero {
        padding: 38px 20px;
    }

    .hapl-ca-hero h1 {
        font-size: 29px;
    }

    .hapl-ca-hero p {
        font-size: 15px;
    }

    .hapl-ca-panel {
        padding: 20px;
    }

    .hapl-ca-panel h2 {
        font-size: 23px;
    }

    .hapl-ca-year summary {
        padding: 16px;
        font-size: 17px;
    }

    .hapl-ca-year-content {
        padding: 15px;
    }

    .hapl-ca-item {
        align-items: flex-start;
        flex-wrap: wrap;
        padding: 16px;
    }

    .hapl-ca-date {
        width: 50px;
        height: 50px;
        flex-basis: 50px;
    }

    .hapl-ca-date-day {
        font-size: 17px;
    }

    .hapl-ca-info {
        flex: 1 1 calc(100% - 65px);
    }

    .hapl-ca-action {
        margin-left: 65px;
        width: calc(100% - 65px);
    }

    .hapl-ca-breadcrumb {
        padding-top: 15px;
        padding-bottom: 15px;
        font-size: 13px;
    }
}
</style>


