/* =========================================================
   HAPL - INVESTOR CONTACT / SHAREHOLDER INFORMATION
   ========================================================= */

.hapl-ic {
    font-family: Arial, sans-serif;
    color: #132b52;
    background: #f7faff;
}

/* =========================================================
   HERO
   ========================================================= */

.hapl-ic-hero {
    position: relative;
    overflow: hidden;
    background: linear-gradient(
        110deg,
        #062b63 0%,
        #0b438c 55%,
        #075ca8 100%
    );
    color: #fff;
    padding: 55px 50px;
}

.hapl-ic-hero-inner {
    max-width: 1200px;
    margin: 0 auto;
}

.hapl-ic-accent {
    width: 38px;
    height: 4px;
    background: #4da3ff;
    margin-bottom: 18px;
}

.hapl-ic-hero h1 {
    margin: 0 0 12px;
    color: #fff;
    font-size: 40px;
    font-weight: 700;
    line-height: 1.2;
}

.hapl-ic-hero p {
    max-width: 800px;
    margin: 0;
    color: #eef6ff;
    font-size: 17px;
    line-height: 1.7;
}

/* =========================================================
   BREADCRUMB
   ========================================================= */

.hapl-ic-breadcrumb {
    max-width: 1200px;
    margin: 0 auto;
    padding: 18px 0;
    font-size: 14px;
    color: #526a8d;
}

.hapl-ic-breadcrumb a {
    color: #0564b8;
    text-decoration: none;
}

.hapl-ic-breadcrumb a:hover {
    text-decoration: underline;
}

/* =========================================================
   CONTENT
   ========================================================= */

.hapl-ic-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 0 40px;
}

.hapl-ic-panel {
    background: #fff;
    border: 1px solid #dce7f5;
    border-radius: 12px;
    padding: 28px;
    box-shadow: 0 4px 18px rgba(20, 65, 110, 0.07);
}

.hapl-ic-panel h2 {
    margin: 0 0 8px;
    color: #0b356d;
    font-size: 28px;
    font-weight: 700;
}

.hapl-ic-intro {
    margin: 0 0 28px;
    color: #607795;
    font-size: 15px;
    line-height: 1.7;
}

/* =========================================================
   CONTACT GRID
   ========================================================= */

.hapl-ic-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18px;
    margin-bottom: 30px;
}

.hapl-ic-card {
    padding: 22px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    transition: all 0.25s ease;
    box-sizing: border-box;
}

.hapl-ic-card:hover {
    border-color: #9fc8f5;
    box-shadow: 0 7px 18px rgba(20, 65, 110, 0.08);
    transform: translateY(-2px);
}

.hapl-ic-card-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 16px;
}

.hapl-ic-icon {
    width: 48px;
    height: 48px;
    flex: 0 0 48px;
    border-radius: 12px;
    background: #edf5ff;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075ca8;
    font-size: 23px;
}

.hapl-ic-card h3 {
    margin: 0;
    color: #103d79;
    font-size: 18px;
}

.hapl-ic-card p {
    margin: 0;
    color: #687d99;
    font-size: 13px;
    line-height: 1.65;
}

/* =========================================================
   DETAILS
   ========================================================= */

.hapl-ic-detail {
    margin-top: 13px;
}

.hapl-ic-detail:first-child {
    margin-top: 0;
}

.hapl-ic-detail strong {
    display: block;
    margin-bottom: 4px;
    color: #31557f;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: .4px;
}

.hapl-ic-detail span {
    display: block;
    color: #526f92;
    font-size: 14px;
    line-height: 1.6;
}

.hapl-ic-detail a {
    color: #0564b8;
    text-decoration: none;
    font-weight: 600;
}

.hapl-ic-detail a:hover {
    text-decoration: underline;
}

/* =========================================================
   FULL WIDTH CARD
   ========================================================= */

.hapl-ic-full {
    margin-bottom: 18px;
}

/* =========================================================
   RTA CARD
   ========================================================= */

.hapl-ic-rta {
    border: 1px solid #b8d6f7;
    border-radius: 12px;
    background: linear-gradient(
        90deg,
        #f3f8ff 0%,
        #ffffff 100%
    );
    padding: 24px;
}

.hapl-ic-rta-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 18px;
}

.hapl-ic-rta h3 {
    margin: 0;
    color: #103d79;
    font-size: 19px;
}

/* =========================================================
   KMP / MANAGEMENT
   ========================================================= */

.hapl-ic-people {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
}

.hapl-ic-person {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 16px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
}

.hapl-ic-person-icon {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    border-radius: 50%;
    background: #edf5ff;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075ca8;
    font-size: 18px;
}

.hapl-ic-person-info {
    min-width: 0;
}

.hapl-ic-person-info h4 {
    margin: 0 0 4px;
    color: #103d79;
    font-size: 14px;
}

.hapl-ic-person-info p {
    margin: 0;
    color: #687d99;
    font-size: 12px;
    line-height: 1.5;
}

/* =========================================================
   BOARD OF DIRECTORS
   ========================================================= */

.hapl-ic-board {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
}

.hapl-ic-board-member {
    padding: 17px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
}

.hapl-ic-board-member h4 {
    margin: 0 0 5px;
    color: #103d79;
    font-size: 15px;
}

.hapl-ic-board-member p {
    margin: 0;
    color: #687d99;
    font-size: 13px;
}

/* =========================================================
   BANKERS / AUDITORS
   ========================================================= */

.hapl-ic-simple-list {
    margin: 0;
    padding: 0;
    list-style: none;
}

.hapl-ic-simple-list li {
    position: relative;
    padding: 10px 0 10px 22px;
    border-bottom: 1px solid #edf2f8;
    color: #526f92;
    font-size: 14px;
}

.hapl-ic-simple-list li:last-child {
    border-bottom: none;
}

.hapl-ic-simple-list li::before {
    content: "•";
    position: absolute;
    left: 4px;
    color: #075ca8;
    font-size: 18px;
}

/* =========================================================
   SHAREHOLDER SERVICES
   ========================================================= */

.hapl-ic-services {
    margin-top: 8px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    overflow: hidden;
}

.hapl-ic-service {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 18px 20px;
    border-bottom: 1px solid #dce7f5;
}

.hapl-ic-service:last-child {
    border-bottom: none;
}

.hapl-ic-service-icon {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    border-radius: 10px;
    background: #edf5ff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
}

.hapl-ic-service-info {
    flex: 1;
}

.hapl-ic-service-info h4 {
    margin: 0 0 4px;
    color: #103d79;
    font-size: 15px;
}

.hapl-ic-service-info p {
    margin: 0;
    color: #687d99;
    font-size: 13px;
    line-height: 1.5;
}

/* =========================================================
   NOTE
   ========================================================= */

.hapl-ic-note {
    margin-top: 26px;
    padding: 18px 20px;
    background: linear-gradient(
        90deg,
        #eef6ff,
        #f7fbff
    );
    border: 1px solid #d8e8fb;
    border-radius: 10px;
}

.hapl-ic-note h4 {
    margin: 0 0 6px;
    color: #123b70;
    font-size: 15px;
}

.hapl-ic-note p {
    margin: 0;
    color: #627894;
    font-size: 13px;
    line-height: 1.6;
}

/* =========================================================
   BACK BUTTON
   ========================================================= */

.hapl-ic-back {
    display: inline-flex;
    align-items: center;
    margin-top: 28px;
    padding: 10px 18px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    color: #075ca8;
    background: #fff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
    transition: all 0.2s ease;
}

.hapl-ic-back:hover {
    background: #075ca8;
    color: #fff;
    border-color: #075ca8;
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 900px) {

    .hapl-ic-hero {
        padding: 45px 25px;
    }

    .hapl-ic-hero h1 {
        font-size: 32px;
    }

    .hapl-ic-breadcrumb,
    .hapl-ic-content {
        padding-left: 20px;
        padding-right: 20px;
    }

    .hapl-ic-grid,
    .hapl-ic-people,
    .hapl-ic-board {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 600px) {

    .hapl-ic-hero {
        padding: 38px 20px;
    }

    .hapl-ic-hero h1 {
        font-size: 29px;
    }

    .hapl-ic-hero p {
        font-size: 15px;
    }

    .hapl-ic-panel {
        padding: 20px;
    }

    .hapl-ic-panel h2 {
        font-size: 23px;
    }

    .hapl-ic-card {
        padding: 18px;
    }

    .hapl-ic-rta {
        padding: 18px;
    }

    .hapl-ic-service {
        align-items: flex-start;
        padding: 16px;
    }

    .hapl-ic-breadcrumb {
        padding-top: 15px;
        padding-bottom: 15px;
        font-size: 13px;
    }
}
</style>


