    box-shadow: 0 4px 18px rgba(20, 65, 110, 0.07);
}

.hapl-lu-panel h2 {
    margin: 0 0 8px;
    color: #0b356d;
    font-size: 28px;
}

.hapl-lu-intro {
    margin: 0 0 28px;
    color: #607795;
    font-size: 15px;
    line-height: 1.7;
}

/* ================= YEAR ================= */

.hapl-lu-year {
    margin-bottom: 32px;
}

.hapl-lu-year-title {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 15px;
}

.hapl-lu-year-title h3 {
    margin: 0;
    color: #102f60;
    font-size: 21px;
}

.hapl-lu-current {
    padding: 5px 10px;
    border-radius: 20px;
    background: #eaf3ff;
    color: #0564b8;
    font-size: 12px;
    font-weight: 700;
}

/* ================= UPDATE CARD ================= */

.hapl-lu-update {
    display: flex;
    align-items: stretch;
    min-height: 105px;
    margin-bottom: 12px;
    border: 1px solid #dce7f5;
    border-radius: 10px;
    background: #fff;
    overflow: hidden;
    transition: all .25s ease;
}

.hapl-lu-update:hover {
    border-color: #9fc8f5;
    box-shadow: 0 7px 18px rgba(20,65,110,.09);
    transform: translateY(-2px);
}

/* ================= DATE ================= */

.hapl-lu-date {
    width: 78px;
    flex: 0 0 78px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    background: #f1f7ff;
    border-right: 1px solid #dce7f5;
    text-align: center;
}

.hapl-lu-date strong {
    color: #075ca8;
    font-size: 24px;
    line-height: 1;
}

.hapl-lu-date span {
    margin-top: 5px;
    color: #607795;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.hapl-lu-date small {
    margin-top: 2px;
    color: #8092aa;
    font-size: 10px;
}

/* ================= ICON ================= */

.hapl-lu-icon {
    width: 58px;
    flex: 0 0 58px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
}

/* ================= INFO ================= */

.hapl-lu-info {
    flex: 1;
    min-width: 0;
    padding: 20px 10px;
}

.hapl-lu-info h4 {
    margin: 0 0 6px;
    color: #103d79;
    font-size: 16px;
    line-height: 1.4;
}

.hapl-lu-info p {
    margin: 0;
    color: #687d99;
    font-size: 13px;
    line-height: 1.55;
}

/* ================= CATEGORY ================= */

.hapl-lu-category {
    display: inline-block;
    margin-top: 7px;
    padding: 4px 9px;
    border-radius: 20px;
    background: #edf5ff;
    color: #075ca8;
    font-size: 11px;
    font-weight: 600;
}

/* ================= ACTION ================= */

.hapl-lu-action {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 105px;
    flex: 0 0 105px;
    padding: 15px;
}

.hapl-lu-action a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 9px 13px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    background: #fff;
    color: #075ca8;
    text-decoration: none;
    font-size: 12px;
    font-weight: 600;
    transition: all .2s ease;
}

.hapl-lu-action a:hover {
    background: #075ca8;
    color: #fff;
}

/* ================= PENDING ================= */

.hapl-lu-pending {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 8px 11px;
    border: 1px solid #dce7f5;
    border-radius: 7px;
    background: #f7faff;
    color: #7a8da5;
    font-size: 11px;
    font-weight: 600;
}

/* ================= NOTE ================= */

.hapl-lu-note {
    margin-top: 25px;
    padding: 18px 20px;
    background: linear-gradient(90deg, #eef6ff, #f7fbff);
    border: 1px solid #d8e8fb;
    border-radius: 10px;
}

.hapl-lu-note h4 {
    margin: 0 0 6px;
    color: #123b70;
    font-size: 15px;
}

.hapl-lu-note p {
    margin: 0;
    color: #627894;
    font-size: 13px;
    line-height: 1.6;
}

/* ================= BACK ================= */

.hapl-lu-back {
    display: inline-flex;
    align-items: center;
    margin-top: 28px;
    padding: 10px 18px;
    border: 1px solid #8ebcf0;
    border-radius: 7px;
    background: #fff;
    color: #075ca8;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
}

.hapl-lu-back:hover {
    background: #075ca8;
    color: #fff;
}

/* ================= MOBILE ================= */

@media (max-width: 700px) {

